-- Publish the requested GTA VI pre-order and its owner-editable homepage slide.
-- Requests collect enquiries only: no payment, stock reservation or free-price checkout.
INSERT OR IGNORE INTO products(id,slug,name,description,category_id,brand,platform,condition,product_type,active,demo,seo_title,seo_description) SELECT 'preorder-gta-vi-ps5','grand-theft-auto-vi-ps5','Grand Theft Auto VI - PS5','Explore Vice City and the state of Leonida in the next Grand Theft Auto from Rockstar Games. PS5 pre-order enquiry. Games Factory Pakistan will confirm final PKR pricing, edition, availability and delivery before accepting an order or payment.',id,'Rockstar Games','PlayStation','New','physical-game',1,0,'GTA VI PS5 Pre-order | Games Factory Pakistan','Enquire about GTA VI for PS5. Final price, edition and availability will be confirmed by Games Factory Pakistan.' FROM categories WHERE slug='games';
INSERT OR IGNORE INTO product_details(product_id,generation,compatibility,region,edition,sale_mode,release_date,deposit_terms,price_on_request,price_unconfirmed,homepage_showcase,preorder_slideshow,preorder_banner_key,preorder_headline,preorder_body) SELECT id,'PS5','PlayStation 5. Not compatible with PlayStation 4.','Region to be confirmed by the team.','Edition to be confirmed before order acceptance.','preorder','2026-11-19','This is a pre-order enquiry, not a confirmed order or stock reservation. The Games Factory team will confirm the final price, edition, availability, payment requirements and cancellation terms before accepting any order or payment. Do not send a deposit until the team provides confirmation. Release dates may change; release-day delivery is not guaranteed.',0,1,0,1,'catalogue/gta-vi-preorder-banner.jpg','GRAND THEFT AUTO VI','Vice City is calling. Enquire about your PS5 pre-order. Price not confirmed yet; our team will confirm the details before payment.' FROM products WHERE slug='grand-theft-auto-vi-ps5';
INSERT OR IGNORE INTO product_variants(id,product_id,sku,name,attributes_json,price_pkr,available,condition) SELECT 'preorder-gta-vi-ps5-v',id,'GFP-GTA-VI-PS5-PREORDER','PS5 - edition to be confirmed','{}',0,1,'New' FROM products WHERE slug='grand-theft-auto-vi-ps5';
INSERT OR IGNORE INTO inventory(id,variant_id,branch_id,quantity_available) SELECT 'preorder-gta-vi-ps5-'||b.id,v.id,b.id,0 FROM branches b CROSS JOIN product_variants v WHERE v.id='preorder-gta-vi-ps5-v';
INSERT OR IGNORE INTO product_images(id,product_id,r2_key,alt_text,is_primary,width,height) SELECT 'preorder-gta-vi-ps5-image',id,'catalogue/gta-vi-preorder-banner.jpg','Grand Theft Auto VI official promotional artwork',1,3840,2160 FROM products WHERE slug='grand-theft-auto-vi-ps5';
INSERT OR IGNORE INTO media_assets(id,r2_key,alt_text,width,height,is_transparent_asset) VALUES('preorder-gta-vi-ps5-banner','catalogue/gta-vi-preorder-banner.jpg','GTA VI pre-order banner - official artwork',3840,2160,0);
